"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[8925],{1625(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>d,default:()=>h,frontMatter:()=>l,metadata:()=>i,toc:()=>p});const i=JSON.parse('{"id":"part1-enterprise-ai-delivery/after-hld-next-steps","title":"After HLD: What the AI Lead Does Next","description":"You\u2019ve written the High-Level Design (HLD) for the Exec Document Q&A pilot. Now you move from \u201cdesign\u201d into alignment \u2192 approvals \u2192 delivery readiness. This tutorial explains the next steps, the artifacts you produce,...","source":"@site/docs/part1-enterprise-ai-delivery/08-after-hld-next-steps.mdx","sourceDirName":"part1-enterprise-ai-delivery","slug":"/part1-enterprise-ai-delivery/08-after-hld-next-steps","permalink":"/tutorials/part1-enterprise-ai-delivery/08-after-hld-next-steps","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":8,"frontMatter":{"title":"After HLD: What the AI Lead Does Next","slug":"/part1-enterprise-ai-delivery/08-after-hld-next-steps","description":"You\u2019ve written the High-Level Design (HLD) for the Exec Document Q&A pilot. Now you move from \u201cdesign\u201d into alignment \u2192 approvals \u2192 delivery readiness. This tutorial explains the next steps, the artifacts you produce,...","sidebar_label":"8. After HLD: next steps","pagination_label":"8. After HLD: next steps","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"7. HLD and service selection","permalink":"/tutorials/part1-enterprise-ai-delivery/07-hld-service-selection"},"next":{"title":"9. Architecture review","permalink":"/tutorials/part1-enterprise-ai-delivery/09-architecture-review"}}');var s=n(4848),a=n(8453),r=n(8172);const o=JSON.parse('{"sourcePath":"part1-enterprise-ai-delivery/08-after-hld-next-steps.html","route":"/part1-enterprise-ai-delivery/08-after-hld-next-steps","kind":"chapter","partId":"part1","partLabel":"Part I - Enterprise AI Delivery Lifecycle","accent":"blue","heading":"After HLD: What You Do Next (AI Lead Under an AI Head)","title":"After HLD: What the AI Lead Does Next","description":"You\u2019ve written the High-Level Design (HLD) for the Exec Document Q&A pilot. Now you move from \u201cdesign\u201d into alignment \u2192 approvals \u2192 delivery readiness. This tutorial explains the next steps, the artifacts you produce,...","readingMinutes":4,"bodyClass":"","normalizeMath":false,"toc":[{"id":"mentalmodel","label":"1) Mental model: what changes after HLD"},{"id":"sequence","label":"2) The next sequence (what you do, step-by-step)"},{"id":"artifacts","label":"3) Artifacts you produce after HLD (practical set)"},{"id":"upmanage","label":"4) Up-managing your AI Head (your manager)"},{"id":"checklist","label":"5) Quick checklist (post-HLD)"}],"html":"<div class=\\"container\\">\\n    \\n    <p class=\\"lead\\">\\n      You\u2019ve written the <strong>High-Level Design (HLD)</strong> for the Exec Document Q&amp;A pilot.\\n      Now you move from \u201cdesign\u201d into <strong>alignment \u2192 approvals \u2192 delivery readiness</strong>.\\n      This tutorial explains the next steps, the artifacts you produce, and how to manage upwards when you have an <strong>AI Head</strong>.\\n    </p>\\n\\n    <ul class=\\"toc\\">\\n      <li><a href=\\"#mentalmodel\\">Mental model</a></li>\\n      <li><a href=\\"#sequence\\">Next sequence</a></li>\\n      <li><a href=\\"#artifacts\\">Artifacts</a></li>\\n      <li><a href=\\"#upmanage\\">Up-managing your AI Head</a></li>\\n      <li><a href=\\"#checklist\\">Checklist</a></li>\\n    </ul>\\n\\n    <h2 id=\\"mentalmodel\\">1) Mental model: what changes after HLD</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        HLD is the point where the system becomes <strong>reviewable</strong>.\\n        The next phase is about making it <strong>approvable</strong> and <strong>buildable</strong>.\\n      </p>\\n\\n      <div class=\\"grid2\\">\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Before (HLD)</div>\\n          <ul>\\n            <li>Boxes &amp; arrows + trust boundaries</li>\\n            <li>Core service choices + alternatives</li>\\n            <li>Key risks + mitigations</li>\\n            <li>Open questions</li>\\n          </ul>\\n        </div>\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">After (execution-ready)</div>\\n          <ul>\\n            <li>Architecture review approval (or approval with conditions)</li>\\n            <li>LLD tasks and sprint backlog</li>\\n            <li>Provisioning tickets in flight (IAM, networking, data access)</li>\\n            <li>Vertical slice milestone defined</li>\\n          </ul>\\n        </div>\\n      </div>\\n\\n      <div class=\\"ok\\">\\n        <strong>Lead-level framing:</strong> after HLD, your job is to remove surprises and unblock dependencies before the team hits them.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"sequence\\">2) The next sequence (what you do, step-by-step)</h2>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"step-1-socialise-the-hld-before-formal-review-24-72-hours\\">Step 1 \u2014 Socialise the HLD before formal review (24\u201372 hours)</h3>\\n      <p><span class=\\"pill\\">Goal</span> Prevent reviewers from seeing the design for the first time in the meeting.</p>\\n      <ul>\\n        <li>Send HLD to: <strong>Security/IAM</strong>, <strong>Platform (GKE)</strong>, <strong>Data Owner</strong>, <strong>Privacy/Risk</strong>, <strong>EM</strong>.</li>\\n        <li>Ask for comments focused on: trust boundaries, data-to-LLM rules, audit logging, access enforcement, retention.</li>\\n        <li>Update HLD and produce a short \u201cOpen Questions / Decisions Needed\u201d list.</li>\\n      </ul>\\n      <div class=\\"callout\\">\\n        <strong>Why this matters:</strong> formal review time is scarce. Pre-alignment increases approval likelihood dramatically.\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"step-2-run-the-architecture-review-and-capture-approval-conditions\\">Step 2 \u2014 Run the Architecture Review (and capture approval conditions)</h3>\\n      <p><span class=\\"pill\\">Goal</span> Get \u201cApproved to build pilot\u201d + clear conditions to satisfy.</p>\\n      <p><strong>Bring:</strong></p>\\n      <ul>\\n        <li>HLD (service choices + alternatives + trust boundaries)</li>\\n        <li>ADRs (why we chose key patterns)</li>\\n        <li>Threat model summary (top risks + mitigations)</li>\\n        <li>Draft go-live gates: audit + eval + leakage tests</li>\\n      </ul>\\n\\n      <p><strong>Leave with:</strong></p>\\n      <ul>\\n        <li>Approval outcome: approved / approved with conditions / rejected</li>\\n        <li>Action items, owners, and deadlines</li>\\n        <li>Any required controls (e.g., redaction policy, log schema, data classification constraints)</li>\\n      </ul>\\n\\n      <div class=\\"warn\\">\\n        <strong>Enterprise reality:</strong> \u201capproved with conditions\u201d is common. Capture conditions precisely and put them in your tracker.\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"step-3-convert-hld-into-lld-tasks-sprint-plan-buildable-backlog\\">Step 3 \u2014 Convert HLD into LLD tasks + sprint plan (buildable backlog)</h3>\\n      <p><span class=\\"pill\\">Goal</span> Turn boxes-and-arrows into implementable stories with owners.</p>\\n      <p>What you do:</p>\\n      <ol>\\n        <li>Define epics: Auth/gating, ingestion, retrieval, prompting/citations, audit/observability, eval harness.</li>\\n        <li>Define the <strong>vertical slice</strong> milestone (end-to-end thin slice early).</li>\\n        <li>Write acceptance criteria (must include safety gates, not just \u201cit works\u201d).</li>\\n      </ol>\\n\\n      <div class=\\"ok\\">\\n        <strong>Vertical slice example:</strong> ingest sample docs \u2192 retrieve with corpus/tenant filters \u2192 answer with citations \u2192 write audit log \u2192 run golden set.\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"step-4-start-provisioning-and-dependency-tickets-immediately\\">Step 4 \u2014 Start provisioning &amp; dependency tickets immediately</h3>\\n      <p><span class=\\"pill\\">Goal</span> Avoid \u201cblocked by approvals\u201d mid-sprint.</p>\\n      <ul>\\n        <li>GKE: namespaces, workload identity/service accounts, CI/CD access, image scanning gates</li>\\n        <li>Data: Cloud SQL instance + private connectivity + roles, GCS buckets + retention/IAM</li>\\n        <li>Async: Pub/Sub topics/subscriptions + DLQ, Cloud Tasks queues</li>\\n        <li>Security: Secret Manager secrets + KMS keys, logging retention rules</li>\\n        <li>Egress: allowlist/proxy approval for the LLM endpoint</li>\\n      </ul>\\n      <div class=\\"callout\\">\\n        <strong>Lead-level behavior:</strong> treat provisioning as part of delivery, not \u201csomeone else will do it.\u201d\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"step-5-engineering-kickoff-internal-to-start-delivery\\">Step 5 \u2014 Engineering kickoff (internal) to start delivery</h3>\\n      <p><span class=\\"pill\\">Goal</span> Align the team on \u201cwhat good looks like\u201d and reduce rework.</p>\\n      <ul>\\n        <li>Confirm vertical slice scope</li>\\n        <li>Agree API contracts (e.g., bootstrap identity, query endpoint)</li>\\n        <li>Agree evaluation gates (golden set baseline + regression runs)</li>\\n        <li>Agree \u201cDefinition of Done\u201d includes logs/tests/dashboards</li>\\n      </ul>\\n    </div>\\n\\n    <h2 id=\\"artifacts\\">3) Artifacts you produce after HLD (practical set)</h2>\\n    <div class=\\"card\\">\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Artifact</th>\\n            <th>Purpose</th>\\n            <th>What it contains (minimum)</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td><strong>Architecture Review Pack</strong></td>\\n            <td>Approval to build</td>\\n            <td>Trust boundaries, identity/access model, data flows, service choices, risks+mitigations</td>\\n          </tr>\\n          <tr>\\n            <td><strong>ADR set</strong></td>\\n            <td>Record \u201cwhy\u201d</td>\\n            <td>Cited-only, tenant isolation, corpus gate, model boundary, eval gates</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Approval Conditions Tracker</strong></td>\\n            <td>Make conditions actionable</td>\\n            <td>Condition, owner, due date, evidence required, status</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Sprint Backlog</strong></td>\\n            <td>Make work buildable</td>\\n            <td>Epics/stories, owners, acceptance criteria, dependencies</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Dependency/Provisioning Tickets</strong></td>\\n            <td>Unblock infra</td>\\n            <td>IAM, networking, secrets, DB, buckets, topics, egress</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    </div>\\n\\n    <h2 id=\\"upmanage\\">4) Up-managing your AI Head (your manager)</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        Your AI Head doesn\u2019t need every detail. They need confidence that risks are controlled and delivery is on track.\\n        The best tool is a short, consistent weekly update.\\n      </p>\\n\\n      <div class=\\"ok\\">\\n        <strong>Weekly \u201cAI Lead pack\u201d (1 page):</strong>\\n        <ul>\\n          <li><strong>Status:</strong> what shipped, what\u2019s demoable</li>\\n          <li><strong>Approvals:</strong> what\u2019s done, what\u2019s blocked, who owns it</li>\\n          <li><strong>Top 3 risks:</strong> and mitigation plan</li>\\n          <li><strong>Decisions/escalations needed:</strong> exactly what you need from them</li>\\n          <li><strong>Next week plan:</strong> vertical slice milestones</li>\\n        </ul>\\n      </div>\\n\\n      <div class=\\"warn\\">\\n        <strong>Lead-level signal:</strong> don\u2019t bring problems without options.\\n        Bring \u201crisk + options + recommended path + what you need from leadership.\u201d\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"checklist\\">5) Quick checklist (post-HLD)</h2>\\n    <div class=\\"card\\">\\n      <ul>\\n        <li>\u2610 HLD socialised with Security/Platform/Data Owner/Privacy before review</li>\\n        <li>\u2610 Architecture review booked and pack sent ahead of time</li>\\n        <li>\u2610 ADRs drafted for key decisions</li>\\n        <li>\u2610 Review outcome captured with explicit conditions and owners</li>\\n        <li>\u2610 Backlog created with vertical slice milestone and acceptance criteria</li>\\n        <li>\u2610 Provisioning tickets raised (IAM, DB, storage, pubsub/tasks, secrets, egress)</li>\\n        <li>\u2610 Team engineering kickoff completed</li>\\n        <li>\u2610 Weekly AI Head update pack started</li>\\n      </ul>\\n\\n      <div class=\\"callout\\">\\n        <strong>Outcome:</strong> you exit the \u201cdesign phase\u201d with approvals in motion, engineering unblocked, and stakeholders aligned.\\n      </div>\\n    </div>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>Planning artifacts</strong>\\n      Maintain an <strong>Approval Conditions Tracker</strong> and a first-two-\\n      sprint backlog for the document Q&amp;A pilot. Order the backlog around a\\n      thin vertical slice before adding breadth.\\n    </div>\\n  </div>"}'),l={title:"After HLD: What the AI Lead Does Next",slug:"/part1-enterprise-ai-delivery/08-after-hld-next-steps",description:"You\u2019ve written the High-Level Design (HLD) for the Exec Document Q&A pilot. Now you move from \u201cdesign\u201d into alignment \u2192 approvals \u2192 delivery readiness. This tutorial explains the next steps, the artifacts you produce,...",sidebar_label:"8. After HLD: next steps",pagination_label:"8. After HLD: next steps",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},p=[];function u(e){return(0,s.jsx)(r.A,{content:o})}function h(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(u,{...e})}):u()}}}]);